css:
*{box-sizing:border-box}
:root{--bg:#f3f4f7;--panel:#fff;--text:#171a21;--muted:#5f6878;--line:#e1e4ea;--accent:#6d4dff;--accent2:#2f6bff;--hover:#eeeaff;--green:#1fb57a;--blue:#2f6bff;--orange:#ff7a1a;--violet:#6d4dff;--amber:#f2a516;--red:#e5484d;--sky:#0ea5e9}
body{margin:0}
.app{width:1200px;height:750px;display:flex;background:var(--bg);color:var(--text);font:14px/1.45 "Segoe UI",system-ui,sans-serif;overflow:hidden}
svg{fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.nav{width:212px;background:var(--panel);border-right:1px solid var(--line);display:flex;flex-direction:column;padding:16px 12px}
.brand{display:flex;align-items:center;gap:9px;padding:2px 6px 4px}
.brand svg{stroke:none}
.word{font-size:20px;font-weight:700;letter-spacing:-.01em}
.word b{font-style:italic;background:linear-gradient(90deg,var(--accent),var(--accent2));-webkit-background-clip:text;color:transparent}
.navcap{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);padding:14px 10px 8px}
.item{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:8px;color:var(--muted);font-weight:500;cursor:pointer;margin-bottom:2px}
.item svg{width:18px;height:18px}
.item:hover{background:var(--bg)}
.item.on{background:var(--hover);color:var(--accent);font-weight:600}
.count{margin-left:auto;font-size:11px;background:var(--accent);color:#fff;border-radius:10px;padding:1px 7px}
.navfoot{margin-top:auto;font-size:12px;color:var(--muted);padding:10px;border-top:1px solid var(--line)}
.navfoot .dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--green);margin-right:6px}
.navfoot small{padding-left:14px}
.main{flex:1;display:flex;flex-direction:column;min-width:0}
.top{display:flex;justify-content:space-between;align-items:center;padding:16px 24px 12px;background:var(--panel);border-bottom:1px solid var(--line)}
h1{margin:0;font-size:22px;letter-spacing:-.01em}
.top p{margin:2px 0 0;color:var(--muted);font-size:13px}
.actions{display:flex;align-items:center;gap:10px}
.actions label{color:var(--muted);font-size:13px}
.combo{position:relative;display:flex;align-items:center;gap:8px;height:34px;padding:0 10px 0 12px;border:1px solid var(--line);border-radius:8px;background:var(--panel);min-width:170px;justify-content:space-between}
.combo svg{width:16px;height:16px;color:var(--muted)}
.menu{display:none;position:absolute;top:38px;left:0;right:0;background:var(--panel);border:1px solid var(--line);border-radius:8px;box-shadow:0 8px 24px rgba(20,20,50,.14);padding:4px;z-index:5}
.combo:hover .menu{display:block}
.menu div{padding:6px 10px;border-radius:6px}
.menu div:hover{background:var(--bg)}
.menu .sel{background:var(--hover);color:var(--accent);font-weight:600}
.menu hr{border:0;border-top:1px solid var(--line);margin:4px 0}
.btn{height:34px;padding:0 14px;border-radius:8px;border:1px solid var(--line);background:var(--panel);color:var(--text);font:inherit;font-weight:500;cursor:pointer}
.btn:hover{border-color:var(--accent);color:var(--accent)}
.toolbar{display:flex;justify-content:space-between;align-items:center;padding:12px 24px 0}
.tabs{display:flex;gap:4px;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:3px}
.tabs a{display:flex;align-items:center;gap:6px;padding:6px 14px;border-radius:7px;color:var(--muted);font-weight:500;cursor:pointer}
.tabs a svg{width:15px;height:15px}
.tabs a.on{background:linear-gradient(90deg,var(--accent),var(--accent2));color:#fff}
.tabs a.add{padding:6px 10px;font-weight:700}
.tools{display:flex;gap:8px}
.tbtn{display:flex;align-items:center;gap:6px;height:32px;padding:0 12px;border-radius:8px;border:1px solid var(--line);background:var(--panel);color:var(--text);font:inherit;font-weight:500;cursor:pointer}
.tbtn svg{width:15px;height:15px}
.tbtn.on{border-color:var(--accent);color:var(--accent);background:var(--hover)}
.tbtn.primary{background:linear-gradient(90deg,var(--accent),var(--accent2));color:#fff;border:0}
.board{flex:1;margin:12px 24px 20px;display:grid;grid-template-columns:repeat(12,1fr);grid-auto-rows:62px;gap:12px;position:relative}
.board.editing{background-image:radial-gradient(circle,rgba(109,77,255,.16) 1.2px,transparent 1.4px);background-size:calc((100% + 12px)/12) 74px;border-radius:10px}
.w{position:relative;background:var(--panel);border:1px solid var(--line);border-radius:12px;box-shadow:0 1px 2px rgba(20,20,50,.05);overflow:hidden}
.w.sel{outline:2px solid var(--accent);outline-offset:-1px}
.stat{padding:14px 16px 0 20px}
.stripe{position:absolute;left:0;top:12px;bottom:12px;width:4px;border-radius:0 4px 4px 0}
.stripe.green,.green{--c:var(--green)}.stripe.blue,.blue{--c:var(--blue)}.stripe.orange,.orange{--c:var(--orange)}.stripe.violet,.violet{--c:var(--violet)}.amber{--c:var(--amber)}.red{--c:var(--red)}
.stripe{background:var(--c)}
.sl{color:var(--muted);font-size:12.5px;font-weight:500}
.sv{font-size:26px;font-weight:700;letter-spacing:-.02em;line-height:1.25}
.sc{font-size:12px;font-weight:600}
.sc.up{color:var(--green)}.sc.down{color:var(--red)}
.sc i{font-style:normal;color:var(--muted);font-weight:400}
.spark{position:absolute;right:12px;top:16px;width:84px;height:30px}
.sp{stroke:var(--c);stroke-width:2.2}
.hover{position:absolute;top:8px;right:8px;display:flex;gap:5px;align-items:center;background:var(--panel);padding:4px 6px;border:1px solid var(--line);border-radius:8px;box-shadow:0 4px 12px rgba(20,20,50,.1)}
.sw{width:13px;height:13px;border-radius:50%}
.sw.on{box-shadow:0 0 0 2px var(--panel),0 0 0 3.5px var(--accent)}
.hx{font-size:11px;color:var(--muted);margin-left:3px}
.grip{position:absolute;right:4px;bottom:4px;width:10px;height:10px;border-right:2px solid var(--muted);border-bottom:2px solid var(--muted);opacity:.5;border-radius:0 0 3px 0}
.wh{display:flex;align-items:center;gap:9px;padding:11px 12px 10px 14px;border-bottom:1px solid var(--line);cursor:move}
.wi{width:26px;height:26px;border-radius:7px;display:grid;place-items:center;background:color-mix(in srgb,var(--c) 15%,transparent);color:var(--c)}
.wi svg{width:15px;height:15px}
.wh b{font-weight:600}
.wb{margin-left:auto;display:flex;gap:4px;color:var(--muted)}
.wb svg{width:26px;height:26px;padding:6px;border-radius:6px;cursor:pointer}
.wb svg:hover{background:var(--bg);color:var(--accent)}
.feed{list-style:none;margin:0;padding:4px 14px}
.feed li{display:flex;align-items:center;gap:12px;padding:9px 0;border-bottom:1px solid var(--line)}
.feed li:last-child{border-bottom:0}
.fi{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:color-mix(in srgb,var(--c) 14%,transparent);color:var(--c);flex:none}
.fi svg{width:15px;height:15px}
.ft{flex:1}
time{color:var(--muted);font-size:12.5px}
.meters{padding:12px 16px}
.m{display:grid;grid-template-columns:1fr auto;row-gap:6px;margin-bottom:16px}
.m span{font-weight:500}
.m em{font-style:normal;color:var(--muted);font-size:12.5px}
.bar{grid-column:1/-1;height:8px;border-radius:4px;background:var(--bg);overflow:hidden}
.bar i{display:block;height:100%;border-radius:4px;background:var(--c)}
